CREATE TABLE IF NOT EXISTS "book_chapters" ("id" TEXT NOT NULL, "book_id" TEXT NOT NULL, "number" INTEGER NOT NULL, "title" TEXT NOT NULL, "chars" INTEGER NOT NULL DEFAULT 0, "content" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "book_reading_progress" ("book_id" TEXT NOT NULL, "chapter_number" INTEGER NOT NULL DEFAULT 1, "scroll_ratio" REAL NOT NULL DEFAULT 0.0, "read_at" INTEGER NOT NULL, PRIMARY KEY ("book_id"));
CREATE TABLE IF NOT EXISTS "book_chapter_notes" ("id" TEXT NOT NULL, "book_id" TEXT NOT NULL, "chapter_number" INTEGER NOT NULL, "note" TEXT NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "book_annotations" ("id" TEXT NOT NULL, "book_id" TEXT NOT NULL, "chapter_number" INTEGER NOT NULL, "start_offset" INTEGER NOT NULL, "end_offset" INTEGER NOT NULL, "quote" TEXT NOT NULL, "prefix_context" TEXT NOT NULL DEFAULT '', "suffix_context" TEXT NOT NULL DEFAULT '', "content_fingerprint" TEXT NOT NULL DEFAULT '', "style" TEXT NOT NULL DEFAULT 'spring_rain', "note" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "co_reading_sessions" ("id" TEXT NOT NULL, "work_type" TEXT NOT NULL, "work_id" TEXT NOT NULL, "work_title" TEXT NOT NULL, "character_id" TEXT NOT NULL, "chapter_ref" TEXT NOT NULL, "chapter_title" TEXT NOT NULL DEFAULT '', "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "status" TEXT NOT NULL DEFAULT 'active', "processed_at" INTEGER NULL, "error" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "co_reading_session_messages" ("session_id" TEXT NOT NULL, "message_id" INTEGER NOT NULL, "message_sync_id" TEXT NULL, "added_at" INTEGER NOT NULL, PRIMARY KEY ("session_id", "message_id"));
CREATE TABLE IF NOT EXISTS "game_definitions" ("id" TEXT NOT NULL, "game_type" TEXT NOT NULL DEFAULT 'card_roleplay', "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "definition_json" TEXT NOT NULL, "thumbnail_path" TEXT NULL, "source_filename" TEXT NOT NULL DEFAULT '', "imported_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "game_sessions" ("id" TEXT NOT NULL, "definition_id" TEXT NULL, "game_type" TEXT NOT NULL DEFAULT 'card_roleplay', "definition_title" TEXT NOT NULL, "definition_snapshot_json" TEXT NOT NULL, "session_title" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "parent_session_id" TEXT NULL, "branch_from_message_id" INTEGER NULL, "world_state_json" TEXT NULL, "story_summary" TEXT NULL, "game_log_injected" INTEGER NOT NULL DEFAULT 0 CHECK ("game_log_injected" IN (0, 1)), "created_at" INTEGER NOT NULL, "last_played_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "game_messages" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "session_id" TEXT NOT NULL, "role" TEXT NOT NULL, "content" TEXT NOT NULL, "message_type" TEXT NOT NULL DEFAULT 'normal', "savepoint_label" TEXT NULL, "timestamp" INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_game_sessions_definition_status ON game_sessions(definition_id, status);
CREATE INDEX IF NOT EXISTS idx_game_sessions_game_type ON game_sessions(game_type);
CREATE INDEX IF NOT EXISTS idx_game_sessions_last_played ON game_sessions(last_played_at);
CREATE INDEX IF NOT EXISTS idx_game_sessions_parent ON game_sessions(parent_session_id);
CREATE INDEX IF NOT EXISTS idx_game_messages_session_ts ON game_messages(session_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_game_messages_type ON game_messages(session_id, message_type);
